python3 - <<'PY'
import json,re,glob,subprocess
# rebuild shas
branches=['rachel','monica','phoebe','joey','chandler','ross']
shas=[]
for b in branches:
    out=subprocess.check_output(['git','rev-list',f'origin/friend/{b}']).decode().split()
    for sha in out:
        msg=subprocess.check_output(['git','show',sha,'--format=%B','--no-patch']).decode()
        if 'Friend-Message: 1' in msg:
            ep=None
            for line in msg.splitlines():
                if line.startswith('Episode:'):
                    ep=line.split(':',1)[1].strip()
            shas.append((sha,b,ep))
rec=set()
for f in glob.glob('S*/*.md'):
    for line in open(f):
        m=re.search(r'Source: friend/\w+ @ ([0-9a-f]{40})', line)
        if m: rec.add(m.group(1))
missing=[x for x in shas if x[0] not in rec]
print("missing now:", len(missing))
for m in missing: print(m)
PY

